CREATE TABLE public.client_staff_permissions (user_id uuid PRIMARY KEY DEFAULT auth.uid(), sensitive_access boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.client_staff_permissions TO authenticated;
GRANT ALL ON public.client_staff_permissions TO service_role;
ALTER TABLE public.client_staff_permissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Client controls staff consent" ON public.client_staff_permissions FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE POLICY "Staff read consent" ON public.client_staff_permissions FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.client_staff_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), staff_id uuid NOT NULL, client_id uuid NOT NULL, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.client_staff_audit TO authenticated;
GRANT ALL ON public.client_staff_audit TO service_role;
ALTER TABLE public.client_staff_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Client and staff read activity" ON public.client_staff_audit FOR SELECT TO authenticated USING (client_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.requested_client() RETURNS uuid LANGUAGE plpgsql STABLE AS $$ DECLARE v text; BEGIN v:=nullif(coalesce(nullif(current_setting('request.headers',true),'')::jsonb->>'x-ddhs-client',''),''); RETURN v::uuid; END $$;
CREATE OR REPLACE FUNCTION public.can_manage_client(p_client uuid,p_sensitive boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND public.has_role(auth.uid(),'admin') AND EXISTS (SELECT 1 FROM public.subscriptions s WHERE s.user_id=p_client AND s.status='active' AND s.plan<>'dg_review') AND (NOT p_sensitive OR EXISTS (SELECT 1 FROM public.client_staff_permissions p WHERE p.user_id=p_client AND p.sensitive_access)) $$;
REVOKE ALL ON FUNCTION public.can_manage_client(uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_manage_client(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.platform_owner(p_sensitive boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql STABLE SET search_path=public AS $$ DECLARE v uuid:=public.requested_client(); BEGIN IF v IS NULL THEN RETURN auth.uid(); END IF; IF NOT public.can_manage_client(v,p_sensitive) THEN RAISE EXCEPTION 'Active subscription and client permission required'; END IF; RETURN v; END $$;
REVOKE ALL ON FUNCTION public.platform_owner(boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.platform_owner(boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.workspace_write() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v uuid:=public.requested_client(); BEGIN IF v IS NOT NULL THEN IF NOT public.can_manage_client(v,TG_TABLE_NAME='workforce_foundation_periods') THEN RAISE EXCEPTION 'Client access denied'; END IF; IF TG_OP='INSERT' AND NEW.user_id=auth.uid() THEN NEW.user_id:=v; END IF; IF TG_OP='DELETE' THEN IF OLD.user_id<>v THEN RAISE EXCEPTION 'Wrong client'; END IF; ELSE IF NEW.user_id<>v THEN RAISE EXCEPTION 'Wrong client'; END IF; END IF; INSERT INTO public.client_staff_audit(staff_id,client_id,action) VALUES(auth.uid(),v,TG_OP||':'||TG_TABLE_NAME); END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
DO $$ DECLARE t text; sensitive boolean; BEGIN FOREACH t IN ARRAY ARRAY['workforce_snapshots','eea12_analyses','barrier_responses','barrier_survey_links','client_share_links','ee_plans','dg_reviews','dg_outcome_analyses','evidence_extractions','plan_gap_analyses','portal_documents','recruitment_vacancies','recruitment_candidates','doel_submissions','reminder_settings','workforce_foundation_periods'] LOOP sensitive:=t='workforce_foundation_periods'; EXECUTE format('CREATE POLICY "Subscribed staff workspace" ON public.%I FOR ALL TO authenticated USING (user_id=public.requested_client() AND public.can_manage_client(user_id,%L)) WITH CHECK (user_id=public.requested_client() AND public.can_manage_client(user_id,%L))',t,sensitive,sensitive); EXECUTE format('CREATE POLICY "Workspace isolation" ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (public.requested_client() IS NULL OR (user_id=public.requested_client() AND public.can_manage_client(user_id,%L))) WITH CHECK (public.requested_client() IS NULL OR (user_id=public.requested_client() AND public.can_manage_client(user_id,%L)))',t,sensitive,sensitive); EXECUTE format('CREATE TRIGGER staff_workspace_write BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.workspace_write()',t); END LOOP; FOREACH t IN ARRAY ARRAY['subscriptions','invoices'] LOOP EXECUTE format('CREATE POLICY "Workspace read isolation" ON public.%I AS RESTRICTIVE FOR SELECT TO authenticated USING (public.requested_client() IS NULL OR (user_id=public.requested_client() AND public.can_manage_client(user_id,false)))',t); EXECUTE format('CREATE POLICY "Subscribed workspace reads" ON public.%I FOR SELECT TO authenticated USING (user_id=public.requested_client() AND public.can_manage_client(user_id,false))',t); END LOOP; END $$;
CREATE POLICY "Subscribed staff client files" ON storage.objects FOR ALL TO authenticated USING (bucket_id='client-documents' AND (storage.foldername(name))[1]=public.requested_client()::text AND public.can_manage_client(public.requested_client(),true)) WITH CHECK (bucket_id='client-documents' AND (storage.foldername(name))[1]=public.requested_client()::text AND public.can_manage_client(public.requested_client(),true));
CREATE POLICY "Subscribed staff candidate CVs" ON storage.objects FOR ALL TO authenticated USING (bucket_id='recruitment-cvs' AND EXISTS (SELECT 1 FROM public.recruitment_vacancies v WHERE v.id::text=(storage.foldername(name))[1] AND v.user_id=public.requested_client() AND public.can_manage_client(v.user_id,true))) WITH CHECK (bucket_id='recruitment-cvs' AND EXISTS (SELECT 1 FROM public.recruitment_vacancies v WHERE v.id::text=(storage.foldername(name))[1] AND v.user_id=public.requested_client() AND public.can_manage_client(v.user_id,true)));
DO $$ DECLARE f text; BEGIN f:=pg_get_functiondef('public.save_workforce_foundation(jsonb,jsonb)'::regprocedure); EXECUTE replace(f,'auth.uid()','public.platform_owner(true)'); f:=pg_get_functiondef('public.delete_workforce_foundation(uuid)'::regprocedure); EXECUTE replace(f,'auth.uid()','public.platform_owner(true)'); END $$;
COMMENT ON TABLE public.client_staff_permissions IS 'Only the account owner grants or revokes sensitive employee access. Staff access also requires an active platform subscription.';